def dereference(entry):
    p=ROOT/entry['source_registry']; raw=p.read_bytes()
    assert hashlib.sha256(raw).hexdigest()==entry['source_registry_sha256']
    value=json.loads(raw)
    for part in entry['json_pointer'].strip('/').split('/'):
        value=value[int(part)] if isinstance(value,list) else value[part]
    digest=hashlib.sha256(json.dumps(value,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()).hexdigest()
    assert digest==entry['entry_sha256'],entry['id']
    assert value['id']==entry['id']
    return value

