    status,obligation,reason,evidence=groups[x['id']]
    rows.append({'id':x['id'],'inherited_reference':x,'reference_hash_verified':True,'prior_status_unchanged':x['source_claimed_status'],'full2_disposition':status,'current_obligation':obligation,'full2_reason':reason,'exact_historical_mechanism':x['description_hint'],'evidence':evidence,'scope':'FIXED-MAIN-v1 mathematical implication, MR-v1, AM-MAIN-v3, SFUNC-v2; literal FIXED final wording separately rejected.'})
