result={'generated_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'registry_sha256':hashlib.sha256(registry_path.read_bytes()).hexdigest(),'inherited_count':164,'local_root_count':len(new),'full2_count':5,'total_count':len(rows),'scope_note':'A scoped review, not blanket reexecution or acceptance of historical claims. Every inherited source status, exact pointer and hash is preserved. Current mechanisms were audited anew; old irrelevant constructions remain outside scope. Final coordinator blind/delivery gates remain separate.','entries':rows}
